package com.example.media.recommendation

import android.content.Context

/** Remove only IDs generated by the Screening device fixtures, including residue from older runs. */
internal fun cleanupScreeningDeviceFixtures(context: Context, extraIds: Collection<String> = emptyList()) {
    ScreeningStore(context).snapshot()
    context.openOrCreateDatabase("screening_learning.db", Context.MODE_PRIVATE, null).use { db ->
        val ids = extraIds.toMutableSet()
        db.rawQuery("SELECT item_id FROM taste_titles WHERE item_id GLOB ? OR item_id GLOB ?",
            arrayOf("screening_test_*", "screening_widget_test_*")).use { cursor ->
            while (cursor.moveToNext()) ids += cursor.getString(0)
        }
        db.beginTransaction()
        try {
            for (id in ids) {
                val keys = mutableSetOf("movie:local:$id", "tv:local:$id", "media:local:$id")
                db.rawQuery("SELECT k FROM taste_titles WHERE item_id = ?", arrayOf(id)).use { cursor ->
                    while (cursor.moveToNext()) keys += cursor.getString(0)
                }
                for (key in keys) {
                    db.execSQL("DELETE FROM taste_surface_heads WHERE id IN (SELECT id FROM taste_publications WHERE k = ?)", arrayOf(key))
                    db.execSQL("DELETE FROM taste_ignored WHERE id IN (SELECT 'feedback:' || rowid FROM feedback WHERE k = ?)", arrayOf(key))
                    db.delete("taste_ignored", "id IN (?, ?)", arrayOf("rating:$key", "reaction:$key"))
                    for (table in listOf("deliveries", "feedback", "signals", "taste_reactions", "taste_history", "taste_publications", "taste_titles"))
                        db.delete(table, "k = ?", arrayOf(key))
                    db.delete("taste_aliases", "k = ? OR alias = ?", arrayOf(key, key))
                }
                db.delete("taste_imports", "id = ?", arrayOf("thumb_$id"))
            }
            db.setTransactionSuccessful()
        } finally { db.endTransaction() }
        val edit = context.getSharedPreferences("cobalt_screening_widgets", Context.MODE_PRIVATE).edit()
        ids.forEach { edit.remove("thumb_$it") }
        edit.commit()
    }
}
